// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint8 dummy) public {
        vm.assume(dummy > 0);

        address player = makeAddr("player");
        vm.deal(player, 10 ether);

        vm.warp(0);
        vm.roll(0);

        uint256 potBefore = c.pot();
        vm.prank(player);
        c.play{value: 10}();
        uint256 potAfter = c.pot();

        assertTrue(potAfter == potBefore + 10);
    }
}
